  1→import { useState, useEffect, useRef } from 'react';
  2→
  3→import './App.css';
  4→import Chessboard from './Chessboard';
  5→import GameList from './components/GameList';
  6→import AuthGate from './components/AuthGate';
  7→import GameSetup from './components/GameSetup';
  8→import JoinGame from './components/JoinGame';
  9→import WaitingRoom from './components/WaitingRoom';
 10→import OnlineChessboard from './components/OnlineChessboard';
 11→import { createGame, saveGame, loadGame, markGamePublished, setCurrentUser } from './utils/gameManager';
 12→import { usePasskeyAuth } from './hooks/usePasskeyAuth';
 13→import { usePasskeyPublish } from './hooks/usePasskeyPublish';
 14→import { useServerAuth } from './hooks/useServerAuth';
 15→import { GAME_SERVER_URL } from './config';
 16→
 17→// Persist/restore online game session across reloads
 18→const SS_ONLINE_KEY = 'online_game_session';
 19→
 20→function saveOnlineSession(view, roomId, inviteCode) {
 21→  if (view === 'online' || view === 'waiting') {
 22→    localStorage.setItem(SS_ONLINE_KEY, JSON.stringify({ view, roomId, inviteCode }));
 23→  } else {
 24→    localStorage.removeItem(SS_ONLINE_KEY);
 25→  }
 26→}
 27→
 28→function loadOnlineSession() {
 29→  try {
 30→    const raw = localStorage.getItem(SS_ONLINE_KEY);
 31→    return raw ? JSON.parse(raw) : null;
 32→  } catch { return null; }
 33→}
 34→
 35→function App() {
 36→  const saved = loadOnlineSession();
 37→  const [view, setView] = useState(saved?.view || 'list');
 38→  const [activeGame, setActiveGame] = useState(null);
 39→  const [publishStatus, setPublishStatus] = useState(null);
 40→
 41→  // Online game state
 42→  const [onlineRoomId, setOnlineRoomId] = useState(saved?.roomId || null);
 43→  const [onlineInviteCode, setOnlineInviteCode] = useState(saved?.inviteCode || null);
 44→
 45→  const passkey = usePasskeyAuth();
 46→  const serverAuth = useServerAuth({
 47→    isAuthenticated: passkey.isAuthenticated,
 48→    account: passkey.account,
 49→    username: passkey.username,
 50→  });
 51→  const { publishGame: passkeyPublish } = usePasskeyPublish({
 52→    account: passkey.account,
 53→    credentialId: passkey.credentialId,
 54→    rawId: passkey.rawId,
 55→  });
 56→
 57→  // Persist online session to sessionStorage on state changes
 58→  useEffect(() => {
 59→    saveOnlineSession(view, onlineRoomId, onlineInviteCode);
 60→  }, [view, onlineRoomId, onlineInviteCode]);
 61→
 62→  // Scope game storage to the authenticated user — must be synchronous
 63→  // so that GameList reads the correct localStorage key on first render.
 64→  // (useEffect would run after child effects, causing a race condition.)
 65→  const prevUserRef = useRef(null);
 66→  const currentAccount = passkey.isAuthenticated ? passkey.account : null;
 67→  if (currentAccount !== prevUserRef.current) {
 68→    prevUserRef.current = currentAccount;
 69→    setCurrentUser(currentAccount);
 70→  }
 71→
 72→  const handleLogout = () => {
 73→    passkey.logout();
 74→    serverAuth.logout();
 75→    setActiveGame(null);
 76→    setPublishStatus(null);
 77→    setOnlineRoomId(null);
 78→    setOnlineInviteCode(null);
 79→    setView('list');
 80→  };
 81→
 82→  const handleNewGame = () => {
 83→    setView('setup');
 84→  };
 85→
 86→  // Local AI game start
 87→  const handleStartLocal = (color) => {
 88→    const engineColor = color === 'white' ? 'black' : 'white';
 89→    const game = createGame(engineColor);
 90→    setActiveGame(game);
 91→    setView('playing');
 92→  };
 93→
 94→  // Online game start
 95→  const handleStartOnline = async (color) => {
 96→    if (!serverAuth.serverToken) return;
 97→
 98→    try {
 99→      const resp = await fetch(`${GAME_SERVER_URL}/api/rooms`, {
100→        method: 'POST',
101→        headers: {
102→          'Content-Type': 'application/json',
103→          'Authorization': `Bearer ${serverAuth.serverToken}`,
104→        },
105→        body: JSON.stringify({ color, opponent: 'human' }),
106→      });
107→
108→      const data = await resp.json();
109→      if (!resp.ok) {
110→        console.error('Create room failed:', data.error);
111→        return;
112→      }
113→
114→      setOnlineRoomId(data.roomId);
115→      setOnlineInviteCode(data.inviteCode);
116→      setView('waiting');
117→    } catch (err) {
118→      console.error('Create room error:', err);
119→    }
120→  };
121→
122→  const handleJoinGame = () => {
123→    setView('join');
124→  };
125→
126→  const handleJoined = (roomId) => {
127→    setOnlineRoomId(roomId);
128→    setView('online');
129→  };
130→
131→  const handleWaitingGameStart = (roomId) => {
132→    setOnlineRoomId(roomId);
133→    setView('online');
134→  };
135→
136→  const handleResumeGame = (gameId) => {
137→    const game = loadGame(gameId);
138→    if (game) {
139→      setActiveGame(game);
140→      setView('playing');
141→    }
142→  };
143→
144→  const handleSave = (state) => {
145→    if (!activeGame) return;
146→    saveGame({ ...state, id: activeGame.id, engineColor: activeGame.engineColor, createdAt: activeGame.createdAt });
147→  };
148→
149→  const handleGameEnd = async (result) => {
150→    if (!activeGame) return;
151→
152→    const latestState = loadGame(activeGame.id);
153→    if (latestState) {
154→      latestState.result = result;
155→      saveGame(latestState);
156→    }
157→    setActiveGame(prev => ({ ...prev, result }));
158→
159→    const finishedGame = latestState || { ...activeGame, result };
160→
161→    setPublishStatus('pending');
162→    const publishResult = await passkeyPublish(finishedGame);
163→
164→    if (publishResult.published) {
165→      setPublishStatus('success');
166→      markGamePublished(finishedGame.id, publishResult.txHash);
167→      setTimeout(() => setPublishStatus(null), 4000);
168→    } else if (['no-contract-address', 'passkey-not-authenticated'].includes(publishResult.reason)) {
169→      setPublishStatus(null);
170→    } else {
171→      setPublishStatus('error');
172→      setTimeout(() => setPublishStatus(null), 5000);
173→    }
174→  };
175→
176→  const handleBackToList = () => {
177→    setActiveGame(null);
178→    setPublishStatus(null);
179→    setOnlineRoomId(null);
180→    setOnlineInviteCode(null);
181→    setView('list');
182→  };
183→
184→  // Unauthenticated: show auth gate only
185→  if (!passkey.isAuthenticated) {
186→    return <AuthGate onSignup={passkey.signup} onLogin={passkey.login} />;
187→  }
188→
189→  return (
190→    <div className="app">
191→      <header className="app-header">
192→        <h1>Chess Board</h1>
193→        <div className="passkey-status">
194→          <span className="passkey-badge" title={passkey.account}>
195→            {passkey.username || passkey.account?.slice(0, 6) + '...' + passkey.account?.slice(-4)}
196→          </span>
197→          {serverAuth.isConnected && <span className="server-badge">Online</span>}
198→          <button className="passkey-logout" onClick={handleLogout}>Logout</button>
199→        </div>
200→      </header>
201→
202→      {publishStatus && (
203→        <div className={`publish-toast ${publishStatus}`}>
204→          {publishStatus === 'pending' && 'Publishing game on-chain...'}
205→          {publishStatus === 'success' && 'Game published on-chain!'}
206→          {publishStatus === 'error' && 'Failed to publish on-chain'}
207→        </div>
208→      )}
209→
210→      {view === 'list' && (
211→        <GameList
212→          onNewGame={handleNewGame}
213→          onResumeGame={handleResumeGame}
214→          onResumeOnline={(roomId) => { setOnlineRoomId(roomId); setView('online'); }}
215→          serverToken={serverAuth.serverToken}
216→        />
217→      )}
218→
219→      {view === 'setup' && (
220→        <GameSetup
221→          onStartLocal={handleStartLocal}
222→          onStartOnline={handleStartOnline}
223→          onJoinGame={handleJoinGame}
224→          onCancel={() => setView('list')}
225→          isServerConnected={serverAuth.isConnected}
226→        />
227→      )}
228→
229→      {view === 'join' && (
230→        <JoinGame
231→          serverToken={serverAuth.serverToken}
232→          onJoined={handleJoined}
233→          onCancel={() => setView('setup')}
234→        />
235→      )}
236→
237→      {view === 'waiting' && (
238→        <WaitingRoom
239→          inviteCode={onlineInviteCode}
240→          serverToken={serverAuth.serverToken}
241→          roomId={onlineRoomId}
242→          onGameStart={handleWaitingGameStart}
243→          onCancel={handleBackToList}
244→        />
245→      )}
246→
247→      {view === 'online' && onlineRoomId && (
248→        <OnlineChessboard
249→          key={onlineRoomId}
250→          serverToken={serverAuth.serverToken}
251→          roomId={onlineRoomId}
252→          onBackToList={handleBackToList}
253→        />
254→      )}
255→
256→      {view === 'playing' && activeGame && (
257→        <Chessboard
258→          key={activeGame.id}
259→          initialState={activeGame}
260→          onSave={handleSave}
261→          onGameEnd={handleGameEnd}
262→          onBackToList={handleBackToList}
263→          engineColorProp={activeGame.engineColor}
264→        />
265→      )}
266→    </div>
267→  );
268→}
269→
270→export default App;
271→

  1→const express = require('express');
  2→const cors = require('cors');
  3→const http = require('http');
  4→const rateLimit = require('express-rate-limit');
  5→const { createDb } = require('./db');
  6→const { authMiddleware } = require('./middleware/auth');
  7→const { createAuthRouter } = require('./routes/auth');
  8→const { createRoomsRouter } = require('./routes/rooms');
  9→const { setupWebSocket } = require('./ws');
 10→const { createStockfishPlayer } = require('./chess/stockfishPlayer');
 11→
 12→const PORT = process.env.PORT || 3001;
 13→
 14→async function main() {
 15→  // Initialize database
 16→  const db = createDb();
 17→
 18→  // Initialize Stockfish (awaited so engine is ready before accepting requests)
 19→  let stockfishPlayer = await createStockfishPlayer();
 20→
 21→  // Create Express app
 22→  const app = express();
 23→
 24→  // Middleware
 25→  app.use(express.json());
 26→  const corsOrigins = process.env.CORS_ORIGINS
 27→    ? process.env.CORS_ORIGINS.split(',')
 28→    : [/^http:\/\/localhost:\d+$/, /^http:\/\/127\.0\.0\.1:\d+$/];
 29→  app.use(cors({
 30→    origin: corsOrigins,
 31→    credentials: true
 32→  }));
 33→
 34→  // Request logging
 35→  app.use((req, res, next) => {
 36→    const start = Date.now();
 37→    res.on('finish', () => {
 38→      const duration = Date.now() - start;
 39→      console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
 40→    });
 41→    next();
 42→  });
 43→
 44→  // Rate limiters
 45→  const isTest = process.env.NODE_ENV === 'test';
 46→
 47→  const signupLimiter = rateLimit({
 48→    windowMs: 60 * 1000, // 1 minute
 49→    max: 5,
 50→    standardHeaders: true,
 51→    legacyHeaders: false,
 52→    skip: () => isTest,
 53→    message: { error: 'Too many signup attempts. Try again in a minute.' }
 54→  });
 55→
 56→  const moveLimiter = rateLimit({
 57→    windowMs: 60 * 1000, // 1 minute
 58→    max: 60,
 59→    keyGenerator: (req) => req.user ? `user:${req.user.id}` : req.ip,
 60→    standardHeaders: true,
 61→    legacyHeaders: false,
 62→    skip: () => isTest,
 63→    message: { error: 'Too many moves. Slow down.' }
 64→  });
 65→
 66→  // Create HTTP server
 67→  const server = http.createServer(app);
 68→
 69→  // Setup WebSocket
 70→  const { broadcast } = setupWebSocket(server, db);
 71→
 72→  // Auth middleware instance
 73→  const auth = authMiddleware(db);
 74→
 75→  // Mount routes
 76→  app.use('/api/auth', signupLimiter, createAuthRouter(db));
 77→
 78→  const roomsRouter = createRoomsRouter(db, {
 79→    broadcast,
 80→    getStockfishPlayer: () => stockfishPlayer
 81→  });
 82→  app.use('/api/rooms', auth, roomsRouter);
 83→
 84→  // Apply move-specific rate limiter to move endpoint
 85→  app.use('/api/rooms/:id/move', moveLimiter);
 86→
 87→  // Health check
 88→  app.get('/api/health', (req, res) => {
 89→    res.json({
 90→      status: 'ok',
 91→      stockfish: !!stockfishPlayer
 92→    });
 93→  });
 94→
 95→  // Room expiry: every 5 minutes, delete stale waiting rooms
 96→  // Delete game_states first (child FK), then rooms (parent)
 97→  const findStaleRooms = db.prepare(`
 98→    SELECT id FROM rooms
 99→    WHERE status = 'waiting'
100→    AND created_at < datetime('now', '-15 minutes')
101→  `);
102→  const deleteGameStateByRoom = db.prepare('DELETE FROM game_states WHERE room_id = ?');
103→  const deleteRoomById = db.prepare('DELETE FROM rooms WHERE id = ?');
104→
105→  const expireStaleRooms = db.transaction(() => {
106→    const stale = findStaleRooms.all();
107→    for (const row of stale) {
108→      deleteGameStateByRoom.run(row.id);
109→      deleteRoomById.run(row.id);
110→    }
111→    return stale.length;
112→  });
113→
114→  setInterval(() => {
115→    const count = expireStaleRooms();
116→    if (count > 0) {
117→      console.log(`Expired ${count} stale waiting room(s)`);
118→    }
119→  }, 5 * 60 * 1000);
120→
121→  // Start server
122→  server.listen(PORT, () => {
123→    console.log(`Chess server listening on http://localhost:${PORT}`);
124→    console.log(`WebSocket available at ws://localhost:${PORT}/api/rooms/:id/ws?token=xxx`);
125→  });
126→
127→  // Graceful shutdown
128→  process.on('SIGINT', () => {
129→    console.log('\nShutting down...');
130→    if (stockfishPlayer) stockfishPlayer.terminate();
131→    db.close();
132→    server.close();
133→    process.exit(0);
134→  });
135→}
136→
137→main().catch(err => {
138→  console.error('Failed to start server:', err);
139→  process.exit(1);
140→});
141→

  1→import { useState, useEffect } from 'react';
  2→import { listGames, deleteGame, clearAllGames, loadGame } from '../utils/gameManager';
  3→import { GAME_SERVER_URL } from '../config';
  4→import './GameList.css';
  5→
  6→function GameList({ onNewGame, onResumeGame, onResumeOnline, serverToken }) {
  7→  const [games, setGames] = useState([]);
  8→  const [onlineGames, setOnlineGames] = useState([]);
  9→
 10→  useEffect(() => {
 11→    setGames(listGames());
 12→  }, []);
 13→
 14→  // Fetch active online games
 15→  useEffect(() => {
 16→    if (!serverToken) return;
 17→
 18→    async function fetchOnlineGames() {
 19→      try {
 20→        const resp = await fetch(`${GAME_SERVER_URL}/api/rooms`, {
 21→          headers: { 'Authorization': `Bearer ${serverToken}` },
 22→        });
 23→        if (!resp.ok) return;
 24→        const data = await resp.json();
 25→        setOnlineGames(data.rooms || []);
 26→      } catch (err) {
 27→        console.error('Failed to fetch online games:', err);
 28→      }
 29→    }
 30→
 31→    fetchOnlineGames();
 32→  }, [serverToken]);
 33→
 34→  const handleDelete = (e, gameId) => {
 35→    e.stopPropagation();
 36→    deleteGame(gameId);
 37→    setGames(listGames());
 38→  };
 39→
 40→  const handleClearAll = () => {
 41→    if (!window.confirm('Delete all saved games?')) return;
 42→    clearAllGames();
 43→    setGames([]);
 44→  };
 45→
 46→  const handleShare = (e, game) => {
 47→    e.stopPropagation();
 48→    const fullGame = loadGame(game.id);
 49→    if (!fullGame) return;
 50→
 51→    const history = fullGame.moveHistory || [];
 52→    const playerColor = game.engineColor === 'white' ? 'black' : 'white';
 53→    const d = new Date(game.updatedAt);
 54→    const dateStr = `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`;
 55→    const timeStr = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;
 56→
 57→    const humanName = playerColor === 'white' ? 'Human' : 'Engine (Stockfish)';
 58→    const engineName = playerColor === 'white' ? 'Engine (Stockfish)' : 'Human';
 59→
 60→    let txSection = '';
 61→    if (game.txHash) {
 62→      txSection = `\n\t<key>Blockchain</key>\n\t<string>Fluent Testnet</string>\n\t<key>TxHash</key>\n\t<string>${game.txHash}</string>\n\t<key>Explorer</key>\n\t<string>https://testnet.fluentscan.xyz/tx/${game.txHash}</string>`;
 63→    }
 64→
 65→    const xml = `<?xml version="1.0" encoding="UTF-8"?>
 66→<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
 67→<plist version="1.0">
 68→<dict>
 69→\t<key>White</key>
 70→\t<string>${humanName}</string>
 71→\t<key>WhiteType</key>
 72→\t<string>${playerColor === 'white' ? 'human' : 'program'}</string>
 73→\t<key>Black</key>
 74→\t<string>${engineName}</string>
 75→\t<key>BlackType</key>
 76→\t<string>${playerColor === 'black' ? 'human' : 'program'}</string>
 77→\t<key>Event</key>
 78→\t<string>vs Stockfish</string>
 79→\t<key>StartDate</key>
 80→\t<string>${dateStr}</string>
 81→\t<key>StartTime</key>
 82→\t<string>${timeStr}</string>
 83→\t<key>Result</key>
 84→\t<string>${game.result}</string>
 85→\t<key>Variant</key>
 86→\t<string>normal</string>
 87→\t<key>Moves</key>
 88→\t<string>
 89→${history.join('\n')}
 90→\t</string>${txSection}
 91→</dict>
 92→</plist>`;
 93→
 94→    const blob = new Blob([xml], { type: 'application/xml' });
 95→    const url = URL.createObjectURL(blob);
 96→    const a = document.createElement('a');
 97→    a.href = url;
 98→    a.download = `Game ${game.id}.game`;
 99→    a.click();
100→    URL.revokeObjectURL(url);
101→  };
102→
103→  const resultLabel = (result) => {
104→    if (result === '1-0') return 'White wins';
105→    if (result === '0-1') return 'Black wins';
106→    if (result === '1/2-1/2') return 'Draw';
107→    return 'In progress';
108→  };
109→
110→  const formatDate = (iso) => {
111→    const d = new Date(iso);
112→    return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
113→  };
114→
115→  return (
116→    <div className="game-list">
117→      <h2>Your Games</h2>
118→      <div className="game-list-actions">
119→        <button className="new-game-btn" onClick={onNewGame}>+ New Game</button>
120→        {games.length > 0 && (
121→          <button className="clear-all-btn" onClick={handleClearAll}>Clear All</button>
122→        )}
123→      </div>
124→
125→      {/* Online games */}
126→      {onlineGames.length > 0 && (
127→        <>
128→          <h3 className="section-label">Online Games</h3>
129→          <div className="game-cards">
130→            {onlineGames.map(room => (
131→              <div key={`online-${room.roomId}`} className="game-card online-card" onClick={() => onResumeOnline(room.roomId)}>
132→                <div className="game-card-header">
133→                  <span className={`game-result ${room.status === 'waiting' ? 'waiting' : 'in-progress'}`}>
134→                    {room.status === 'waiting' ? 'Waiting for opponent' : `${room.currentTurn}'s turn`}
135→                  </span>
136→                  <span className="online-badge">Online</span>
137→                </div>
138→                <div className="game-card-body">
139→                  <span>{room.white || '?'} vs {room.black || '?'}</span>
140→                  <span>{room.moveCount} moves</span>
141→                </div>
142→                <div className="game-card-footer">
143→                  Playing as {room.myColor} &middot; {formatDate(room.updatedAt)}
144→                </div>
145→              </div>
146→            ))}
147→          </div>
148→        </>
149→      )}
150→
151→      {/* Local games */}
152→      {games.length > 0 && (
153→        <>
154→          {onlineGames.length > 0 && <h3 className="section-label">Local Games</h3>}
155→          <div className="game-cards">
156→            {games.map(game => (
157→              <div key={game.id} className="game-card" onClick={() => onResumeGame(game.id)}>
158→                <div className="game-card-header">
159→                  <span className={`game-result ${game.result === '*' ? 'in-progress' : 'finished'}`}>
160→                    {resultLabel(game.result)}
161→                  </span>
162→                  {game.txHash && (
163→                    <a
164→                      href={`https://testnet.fluentscan.xyz/tx/${game.txHash}`}
165→                      target="_blank"
166→                      rel="noopener noreferrer"
167→                      className="onchain-badge"
168→                      onClick={(e) => e.stopPropagation()}
169→                      title="View on-chain transaction"
170→                    >
171→                      On-chain
172→                    </a>
173→                  )}
174→                  <div className="card-actions">
175→                    {game.result !== '*' && (
176→                      <button
177→                        className="share-btn"
178→                        onClick={(e) => handleShare(e, game)}
179→                        title="Download game record as XML"
180→                      >
181→                        Share
182→                      </button>
183→                    )}
184→                    <button className="delete-btn" onClick={(e) => handleDelete(e, game.id)} title="Delete game">
185→                      &times;
186→                    </button>
187→                  </div>
188→                </div>
189→                <div className="game-card-body">
190→                  <span>Playing as {game.engineColor === 'white' ? 'Black' : 'White'}</span>
191→                  <span>{game.moveCount} moves</span>
192→                </div>
193→                <div className="game-card-footer">
194→                  {formatDate(game.updatedAt)}
195→                </div>
196→              </div>
197→            ))}
198→          </div>
199→        </>
200→      )}
201→
202→      {games.length === 0 && onlineGames.length === 0 && (
203→        <p className="no-games">No saved games yet. Start a new game!</p>
204→      )}
205→    </div>
206→  );
207→}
208→
209→export default GameList;
