  1→const express = require('express');
  2→const { v4: uuidv4 } = require('uuid');
  3→const {
  4→  createInitialGameState, serializeGameState, deserializeGameState,
  5→  parseMove, isMoveLegal, getLegalMoves, applyMove, getGameResult,
  6→  boardToFEN, indexToAlgebraic
  7→} = require('../chess/gameLogic');
  8→
  9→const CHESS_WORDS = ['ROOK', 'KING', 'PAWN', 'MATE', 'MOVE', 'PLAY', 'GAME', 'DRAW'];
 10→
 11→function generateInviteCode(db) {
 12→  const checkCode = db.prepare('SELECT id FROM rooms WHERE invite_code = ?');
 13→  for (let attempt = 0; attempt < 20; attempt++) {
 14→    const word = CHESS_WORDS[Math.floor(Math.random() * CHESS_WORDS.length)];
 15→    const num = String(Math.floor(Math.random() * 100)).padStart(2, '0');
 16→    const code = word + num;
 17→    if (!checkCode.get(code)) {
 18→      return code;
 19→    }
 20→  }
 21→  // Fallback to UUID prefix if all collide (extremely unlikely)
 22→  return uuidv4().slice(0, 8).toUpperCase();
 23→}
 24→
 25→function createRoomsRouter(db, { broadcast, getStockfishPlayer }) {
 26→  const router = express.Router();
 27→
 28→  // Prepared statements
 29→  const insertRoom = db.prepare(`
 30→    INSERT INTO rooms (invite_code, white_user_id, black_user_id, status, is_stockfish, stockfish_level)
 31→    VALUES (?, ?, ?, ?, ?, ?)
 32→  `);
 33→  const insertGameState = db.prepare(`
 34→    INSERT INTO game_states (room_id, board, current_turn, move_history, en_passant_target, moved_pieces, half_move_clock, position_history)
 35→    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
 36→  `);
 37→  const findRoomByCode = db.prepare('SELECT * FROM rooms WHERE invite_code = ?');
 38→  const findRoomById = db.prepare('SELECT * FROM rooms WHERE id = ?');
 39→  const findGameState = db.prepare('SELECT * FROM game_states WHERE room_id = ?');
 40→  const updateRoomJoin = db.prepare(`
 41→    UPDATE rooms SET white_user_id = ?, black_user_id = ?, status = 'playing', updated_at = datetime('now')
 42→    WHERE id = ?
 43→  `);
 44→  const updateGameState = db.prepare(`
 45→    UPDATE game_states
 46→    SET board = ?, current_turn = ?, move_history = ?, en_passant_target = ?,
 47→        moved_pieces = ?, half_move_clock = ?, position_history = ?, updated_at = datetime('now')
 48→    WHERE room_id = ?
 49→  `);
 50→  const updateRoomResult = db.prepare(`
 51→    UPDATE rooms SET status = 'finished', result = ?, updated_at = datetime('now') WHERE id = ?
 52→  `);
 53→  const findUserById = db.prepare('SELECT id, username FROM users WHERE id = ?');
 54→
 55→  // Stockfish system user
 56→  const findStockfishUser = db.prepare("SELECT id FROM users WHERE username = '__stockfish__'");
 57→  const insertStockfishUser = db.prepare("INSERT OR IGNORE INTO users (username, token) VALUES ('__stockfish__', '__stockfish_token__')");
 58→
 59→  function getOrCreateStockfishUser() {
 60→    let user = findStockfishUser.get();
 61→    if (!user) {
 62→      insertStockfishUser.run();
 63→      user = findStockfishUser.get();
 64→    }
 65→    return user.id;
 66→  }
 67→
 68→  // Track consecutive illegal moves per room per user
 69→  const illegalMoveCounters = new Map(); // `${roomId}:${userId}` -> count
 70→
 71→  function getIllegalKey(roomId, userId) {
 72→    return `${roomId}:${userId}`;
 73→  }
 74→
 75→  // POST /api/rooms — create a new room
 76→  router.post('/', (req, res) => {
 77→    const { color, opponent, stockfishLevel } = req.body;
 78→    const userId = req.user.id;
 79→
 80→    // Determine player's color
 81→    let chosenColor = color;
 82→    if (!chosenColor || chosenColor === 'random') {
 83→      chosenColor = Math.random() < 0.5 ? 'white' : 'black';
 84→    }
 85→    if (chosenColor !== 'white' && chosenColor !== 'black') {
 86→      return res.status(400).json({ error: 'color must be "white", "black", or "random"' });
 87→    }
 88→
 89→    const inviteCode = generateInviteCode(db);
 90→    const isStockfish = opponent === 'stockfish' ? 1 : 0;
 91→    const sfLevel = isStockfish ? (stockfishLevel || 10) : null;
 92→
 93→    // Check Stockfish availability
 94→    if (isStockfish) {
 95→      const sfPlayer = getStockfishPlayer();
 96→      if (!sfPlayer) {
 97→        return res.status(503).json({ error: 'Stockfish engine is not available on this server' });
 98→      }
 99→    }
100→
101→    let whiteUserId = chosenColor === 'white' ? userId : null;
102→    let blackUserId = chosenColor === 'black' ? userId : null;
103→    let status = 'waiting';
104→
105→    // If Stockfish opponent, fill the other seat immediately
106→    if (isStockfish) {
107→      const sfUserId = getOrCreateStockfishUser();
108→      if (chosenColor === 'white') {
109→        blackUserId = sfUserId;
110→      } else {
111→        whiteUserId = sfUserId;
112→      }
113→      status = 'playing';
114→    }
115→
116→    const createRoom = db.transaction(() => {
117→      const result = insertRoom.run(inviteCode, whiteUserId, blackUserId, status, isStockfish, sfLevel);
118→      const roomId = result.lastInsertRowid;
119→
120→      // Initialize game state
121→      const gs = createInitialGameState();
122→      const s = serializeGameState(gs);
123→      insertGameState.run(roomId, s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history);
124→
125→      return roomId;
126→    });
127→
128→    const roomId = createRoom();
129→
130→    // If Stockfish plays first (player chose black), trigger Stockfish move
131→    if (isStockfish && chosenColor === 'black') {
132→      triggerStockfishMove(roomId);
133→    }
134→
135→    res.status(201).json({
136→      roomId: Number(roomId),
137→      inviteCode,
138→      color: chosenColor
139→    });
140→  });
141→
142→  // POST /api/rooms/join — join a room by invite code
143→  router.post('/join', (req, res) => {
144→    const { inviteCode } = req.body;
145→    const userId = req.user.id;
146→
147→    if (!inviteCode || typeof inviteCode !== 'string') {
148→      return res.status(400).json({ error: 'inviteCode is required' });
149→    }
150→
151→    const room = findRoomByCode.get(inviteCode.toUpperCase());
152→    if (!room) {
153→      return res.status(404).json({ error: 'Room not found' });
154→    }
155→
156→    if (room.status !== 'waiting') {
157→      return res.status(400).json({ error: 'Room is no longer accepting players' });
158→    }
159→
160→    // Don't let the creator join their own room
161→    if (room.white_user_id === userId || room.black_user_id === userId) {
162→      return res.status(400).json({ error: 'You are already in this room' });
163→    }
164→
165→    // Assign joiner to empty seat
166→    let whiteUserId = room.white_user_id;
167→    let blackUserId = room.black_user_id;
168→    let myColor;
169→
170→    if (!whiteUserId) {
171→      whiteUserId = userId;
172→      myColor = 'white';
173→    } else {
174→      blackUserId = userId;
175→      myColor = 'black';
176→    }
177→
178→    updateRoomJoin.run(whiteUserId, blackUserId, room.id);
179→
180→    // Broadcast join event
181→    broadcast(room.id, 'join', {
182→      userId,
183→      username: req.user.username,
184→      color: myColor
185→    });
186→
187→    res.json({
188→      roomId: room.id,
189→      color: myColor
190→    });
191→  });
192→
193→  // GET /api/rooms — list user's active rooms
194→  const findUserRooms = db.prepare(`
195→    SELECT r.*, gs.current_turn, gs.move_history
196→    FROM rooms r
197→    JOIN game_states gs ON gs.room_id = r.id
198→    WHERE (r.white_user_id = ? OR r.black_user_id = ?)
199→    AND r.status IN ('waiting', 'playing')
200→    ORDER BY r.updated_at DESC
201→  `);
202→
203→  router.get('/', (req, res) => {
204→    const userId = req.user.id;
205→    const rows = findUserRooms.all(userId, userId);
206→
207→    const rooms = rows.map(r => {
208→      const whiteUser = r.white_user_id ? findUserById.get(r.white_user_id) : null;
209→      const blackUser = r.black_user_id ? findUserById.get(r.black_user_id) : null;
210→      const moveHistory = r.move_history ? JSON.parse(r.move_history) : [];
211→
212→      return {
213→        roomId: r.id,
214→        inviteCode: r.invite_code,
215→        status: r.status,
216→        white: whiteUser ? whiteUser.username : null,
217→        black: blackUser ? blackUser.username : null,
218→        myColor: r.white_user_id === userId ? 'white' : 'black',
219→        currentTurn: r.current_turn,
220→        moveCount: moveHistory.length,
221→        updatedAt: r.updated_at,
222→      };
223→    });
224→
225→    res.json({ rooms });
226→  });
227→
228→  // GET /api/rooms/:id — get room and game state
229→  router.get('/:id', (req, res) => {
230→    const roomId = parseInt(req.params.id);
231→    if (isNaN(roomId)) {
232→      return res.status(400).json({ error: 'Invalid room ID' });
233→    }
234→
235→    const room = findRoomById.get(roomId);
236→    if (!room) {
237→      return res.status(404).json({ error: 'Room not found' });
238→    }
239→
240→    const gsRow = findGameState.get(roomId);
241→    if (!gsRow) {
242→      return res.status(404).json({ error: 'Game state not found' });
243→    }
244→
245→    const gameState = deserializeGameState(gsRow);
246→    const fen = boardToFEN(gameState);
247→    const legalMoves = room.status === 'playing' ? getLegalMoves(gameState) : [];
248→
249→    // Determine caller's color
250→    let myColor = null;
251→    if (req.user.id === room.white_user_id) myColor = 'white';
252→    else if (req.user.id === room.black_user_id) myColor = 'black';
253→
254→    // Get player names
255→    const whiteUser = room.white_user_id ? findUserById.get(room.white_user_id) : null;
256→    const blackUser = room.black_user_id ? findUserById.get(room.black_user_id) : null;
257→
258→    res.json({
259→      roomId: room.id,
260→      inviteCode: room.invite_code,
261→      status: room.status,
262→      isStockfish: !!room.is_stockfish,
263→      stockfishLevel: room.stockfish_level,
264→      result: room.result,
265→      white: whiteUser ? whiteUser.username : null,
266→      black: blackUser ? blackUser.username : null,
267→      myColor,
268→      fen,
269→      currentTurn: gameState.currentTurn,
270→      moveHistory: gameState.moveHistory,
271→      legalMoves,
272→      board: gameState.board
273→    });
274→  });
275→
276→  // POST /api/rooms/:id/move — submit a move
277→  router.post('/:id/move', (req, res) => {
278→    const roomId = parseInt(req.params.id);
279→    if (isNaN(roomId)) {
280→      return res.status(400).json({ error: 'Invalid room ID' });
281→    }
282→
283→    const { move } = req.body;
284→    if (!move || typeof move !== 'string') {
285→      return res.status(400).json({ error: 'move is required (UCI format, e.g. "e2e4")' });
286→    }
287→
288→    const parsed = parseMove(move);
289→    if (!parsed) {
290→      return res.status(400).json({ error: 'Invalid move format. Use UCI notation (e.g. "e2e4", "e7e8q")' });
291→    }
292→
293→    // Use a transaction to prevent race conditions
294→    const submitMove = db.transaction(() => {
295→      const room = findRoomById.get(roomId);
296→      if (!room) {
297→        return { status: 404, body: { error: 'Room not found' } };
298→      }
299→
300→      if (room.status !== 'playing') {
301→        return { status: 400, body: { error: 'Game is not in progress' } };
302→      }
303→
304→      // Verify it's this player's turn
305→      const gsRow = findGameState.get(roomId);
306→      const gameState = deserializeGameState(gsRow);
307→
308→      let expectedUserId;
309→      if (gameState.currentTurn === 'white') {
310→        expectedUserId = room.white_user_id;
311→      } else {
312→        expectedUserId = room.black_user_id;
313→      }
314→
315→      if (req.user.id !== expectedUserId) {
316→        return { status: 403, body: { error: 'Not your turn' } };
317→      }
318→
319→      // Check move legality
320→      const legality = isMoveLegal(gameState, parsed.from, parsed.to, parsed.promotion);
321→
322→      if (!legality.legal) {
323→        // Track consecutive illegal moves
324→        const key = getIllegalKey(roomId, req.user.id);
325→        const count = (illegalMoveCounters.get(key) || 0) + 1;
326→        illegalMoveCounters.set(key, count);
327→
328→        if (count >= 3) {
329→          // Forfeit the game
330→          const loser = gameState.currentTurn;
331→          const result = loser === 'white' ? '0-1' : '1-0';
332→          updateRoomResult.run(result, roomId);
333→          illegalMoveCounters.delete(key);
334→
335→          broadcast(roomId, 'gameOver', { result, reason: 'illegal_move_forfeit' });
336→
337→          return {
338→            status: 400,
339→            body: {
340→              error: legality.reason,
341→              forfeit: true,
342→              result,
343→              reason: 'Too many consecutive illegal moves (3)'
344→            }
345→          };
346→        }
347→
348→        const legalMoves = getLegalMoves(gameState);
349→        return {
350→          status: 400,
351→          body: {
352→            error: legality.reason,
353→            illegalMoveCount: count,
354→            legalMoves
355→          }
356→        };
357→      }
358→
359→      // Reset illegal move counter on legal move
360→      const key = getIllegalKey(roomId, req.user.id);
361→      illegalMoveCounters.delete(key);
362→
363→      // Apply the move
364→      const newGameState = applyMove(gameState, parsed.from, parsed.to, parsed.promotion);
365→
366→      // Check game result
367→      const gameResult = getGameResult(newGameState);
368→
369→      // Persist to SQLite
370→      const s = serializeGameState(newGameState);
371→      updateGameState.run(s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history, roomId);
372→
373→      if (gameResult.over) {
374→        updateRoomResult.run(gameResult.result, roomId);
375→      }
376→
377→      const fen = boardToFEN(newGameState);
378→
379→      const newLegalMoves = gameResult.over ? [] : getLegalMoves(newGameState);
380→
381→      return {
382→        status: 200,
383→        body: {
384→          ok: true,
385→          fen,
386→          move: move,
387→          board: newGameState.board,
388→          currentTurn: newGameState.currentTurn,
389→          moveHistory: newGameState.moveHistory,
390→          legalMoves: newLegalMoves,
391→          gameOver: gameResult.over,
392→          result: gameResult.over ? gameResult.result : undefined,
393→          reason: gameResult.over ? gameResult.reason : undefined
394→        },
395→        newGameState,
396→        gameResult,
397→        room
398→      };
399→    });
400→
401→    const txResult = submitMove();
402→    res.status(txResult.status).json(txResult.body);
403→
404→    // Post-transaction side effects
405→    if (txResult.status === 200) {
406→      // Broadcast move with full state so opponent doesn't need to re-fetch
407→      // Reuse legalMoves already computed in the transaction
408→      broadcast(roomId, 'move', {
409→        move,
410→        fen: txResult.body.fen,
411→        board: txResult.newGameState.board,
412→        currentTurn: txResult.newGameState.currentTurn,
413→        moveHistory: txResult.newGameState.moveHistory,
414→        legalMoves: txResult.body.legalMoves
415→      }, req.user.id);
416→
417→      if (txResult.gameResult.over) {
418→        broadcast(roomId, 'gameOver', {
419→          result: txResult.gameResult.result,
420→          reason: txResult.gameResult.reason
421→        });
422→      }
423→
424→      // If AvE and now Stockfish's turn, trigger async Stockfish move
425→      if (!txResult.gameResult.over && txResult.room.is_stockfish) {
426→        const sfUserId = getOrCreateStockfishUser();
427→        const nextTurn = txResult.newGameState.currentTurn;
428→        const nextUserId = nextTurn === 'white' ? txResult.room.white_user_id : txResult.room.black_user_id;
429→        if (nextUserId === sfUserId) {
430→          triggerStockfishMove(roomId);
431→        }
432→      }
433→    }
434→  });
435→
436→  // Resign
437→  router.post('/:id/resign', (req, res) => {
438→    const roomId = parseInt(req.params.id);
439→    if (isNaN(roomId)) {
440→      return res.status(400).json({ error: 'Invalid room ID' });
441→    }
442→
443→    const submitResign = db.transaction(() => {
444→      const room = findRoomById.get(roomId);
445→      if (!room) {
446→        return { status: 404, body: { error: 'Room not found' } };
447→      }
448→
449→      if (room.status !== 'playing') {
450→        return { status: 400, body: { error: 'Game is not in progress' } };
451→      }
452→
453→      const isWhite = req.user.id === room.white_user_id;
454→      const isBlack = req.user.id === room.black_user_id;
455→
456→      if (!isWhite && !isBlack) {
457→        return { status: 403, body: { error: 'You are not a player in this game' } };
458→      }
459→
460→      const result = isWhite ? '0-1' : '1-0';
461→      updateRoomResult.run(result, roomId);
462→
463→      return {
464→        status: 200,
465→        body: { ok: true, result },
466→        result,
467→        resignedColor: isWhite ? 'white' : 'black'
468→      };
469→    });
470→
471→    const txResult = submitResign();
472→    res.status(txResult.status).json(txResult.body);
473→
474→    if (txResult.status === 200) {
475→      broadcast(roomId, 'gameOver', {
476→        result: txResult.result,
477→        reason: 'resignation'
478→      });
479→    }
480→  });
481→
482→  // Async Stockfish move
483→  function triggerStockfishMove(roomId) {
484→    setTimeout(async () => {
485→      try {
486→        const sfPlayer = getStockfishPlayer();
487→        if (!sfPlayer) return;
488→
489→        const room = findRoomById.get(roomId);
490→        if (!room || room.status !== 'playing') return;
491→
492→        const gsRow = findGameState.get(roomId);
493→        const gameState = deserializeGameState(gsRow);
494→        const fen = boardToFEN(gameState);
495→
496→        const bestMove = await sfPlayer.getBestMove(fen, room.stockfish_level);
497→        if (!bestMove) return;
498→
499→        const moveStr = bestMove.from + bestMove.to + (bestMove.promotion || '');
500→
501→        // Apply Stockfish's move within a transaction
502→        const sfSubmit = db.transaction(() => {
503→          // Re-read to avoid stale state
504→          const freshGsRow = findGameState.get(roomId);
505→          const freshGameState = deserializeGameState(freshGsRow);
506→
507→          const parsed = parseMove(moveStr);
508→          if (!parsed) return null;
509→
510→          const legality = isMoveLegal(freshGameState, parsed.from, parsed.to, parsed.promotion);
511→          if (!legality.legal) {
512→            console.error(`Stockfish made illegal move: ${moveStr} — ${legality.reason}`);
513→            return null;
514→          }
515→
516→          const newGameState = applyMove(freshGameState, parsed.from, parsed.to, parsed.promotion);
517→          const gameResult = getGameResult(newGameState);
518→
519→          const s = serializeGameState(newGameState);
520→          updateGameState.run(s.board, s.current_turn, s.move_history, s.en_passant_target, s.moved_pieces, s.half_move_clock, s.position_history, roomId);
521→
522→          if (gameResult.over) {
523→            updateRoomResult.run(gameResult.result, roomId);
524→          }
525→
526→          return { newGameState, gameResult, moveStr };
527→        });
528→
529→        const result = sfSubmit();
530→        if (!result) return;
531→
532→        const newFen = boardToFEN(result.newGameState);
533→
534→        broadcast(roomId, 'move', {
535→          move: result.moveStr,
536→          fen: newFen,
537→          currentTurn: result.newGameState.currentTurn,
538→          moveHistory: result.newGameState.moveHistory
539→        });
540→
541→        if (result.gameResult.over) {
542→          broadcast(roomId, 'gameOver', {
543→            result: result.gameResult.result,
544→            reason: result.gameResult.reason
545→          });
546→        }
547→      } catch (err) {
548→        console.error('Stockfish move error:', err);
549→      }
550→    }, 100); // Small delay to let the HTTP response complete first
551→  }
552→
553→  return router;
554→}
555→
556→module.exports = { createRoomsRouter };
