 13→      body: JSON.stringify({ username }),
 14→    });
 15→    const body = await res.json();
 16→    if (!res.ok) throw new ApiError(res.status, body.error || 'Signup failed');
 17→    return body;
 18→  }
 19→
 20→  async createRoom(token, color) {
 21→    const res = await fetch(`${this.serverUrl}/api/rooms`, {
 22→      method: 'POST',
 23→      headers: {
 24→        'Content-Type': 'application/json',
 25→        Authorization: `Bearer ${token}`,
 26→      },
 27→      body: JSON.stringify({ color }),
 28→    });
 29→    const body = await res.json();
 30→    if (!res.ok) throw new ApiError(res.status, body.error || 'Failed to create room');
 31→    return body;
 32→  }
 33→
 34→  async joinRoom(token, inviteCode) {
 35→    const res = await fetch(`${this.serverUrl}/api/rooms/join`, {
 36→      method: 'POST',
 37→      headers: {
 38→        'Content-Type': 'application/json',
 39→        Authorization: `Bearer ${token}`,
 40→      },
 41→      body: JSON.stringify({ inviteCode }),
 42→    });
 43→    const body = await res.json();
 44→    if (!res.ok) throw new ApiError(res.status, body.error || 'Failed to join room');
 45→    return body;
 46→  }
 47→
 48→  async getRoomState(token, roomId) {
 49→    const res = await fetch(`${this.serverUrl}/api/rooms/${roomId}`, {
 50→      headers: { Authorization: `Bearer ${token}` },
 51→    });
 52→    const body = await res.json();
 53→    if (!res.ok) throw new ApiError(res.status, body.error || 'Failed to get room state');
 54→    return body;
 55→  }
 56→
 57→  async submitMove(token, roomId, move) {
 58→    const res = await fetch(`${this.serverUrl}/api/rooms/${roomId}/move`, {
 59→      method: 'POST',
 60→      headers: {
 61→        'Content-Type': 'application/json',
 62→        Authorization: `Bearer ${token}`,
 63→      },
 64→      body: JSON.stringify({ move }),
 65→    });
 66→    const body = await res.json();
 67→    if (!res.ok) throw new ApiError(res.status, body.error || 'Move failed', body);
 68→    return body;
 69→  }
 70→
 71→  async resign(token, roomId) {
 72→    const res = await fetch(`${this.serverUrl}/api/rooms/${roomId}/resign`, {
 73→      method: 'POST',
 74→      headers: { Authorization: `Bearer ${token}` },
 75→    });
 76→    const body = await res.json();
 77→    if (!res.ok) throw new ApiError(res.status, body.error || 'Resign failed');
 78→    return body;
 79→  }
 80→
 81→  waitForEvent(token, roomId, targetEvents, timeoutMs = 300000) {
 82→    return new Promise((resolve, reject) => {
 83→      const wsUrl = `${this.wsUrl}/api/rooms/${roomId}/ws?token=${token}`;
 84→      const ws = new WebSocket(wsUrl);
 85→
 86→      const timer = setTimeout(() => {
 87→        ws.close();
 88→        reject(new Error(`Timed out waiting for events: ${targetEvents.join(', ')}`));
 89→      }, timeoutMs);
 90→
 91→      ws.on('message', (data) => {
 92→        try {
 93→          const msg = JSON.parse(data.toString());
 94→          if (targetEvents.includes(msg.event)) {
 95→            clearTimeout(timer);
 96→            ws.close();
 97→            resolve(msg);
 98→          }
 99→        } catch {
100→          // ignore malformed messages
101→        }
102→      });
103→
104→      ws.on('error', (err) => {
105→        clearTimeout(timer);
106→        ws.close();
107→        reject(new Error(`WebSocket error: ${err.message}`));
108→      });
109→
110→      ws.on('close', (code) => {
111→        clearTimeout(timer);
112→        // Only reject if we haven't resolved yet
113→        if (code !== 1000) {
114→          reject(new Error(`WebSocket closed unexpectedly (code ${code})`));
115→        }
116→      });
117→    });
118→  }
119→}
