  5→export function useOnlineGame({ serverToken, roomId }) {
  6→  const [board, setBoard] = useState(null);
  7→  const [currentTurn, setCurrentTurn] = useState(null);
  8→  const [myColor, setMyColor] = useState(null);
  9→  const [legalMoves, setLegalMoves] = useState([]);
 10→  const [moveHistory, setMoveHistory] = useState([]);
 11→  const [gameResult, setGameResult] = useState(null);
 12→  const [status, setStatus] = useState('loading'); // loading | waiting | playing | finished | error
 13→  const [room, setRoom] = useState(null);
 14→  const [error, setError] = useState(null);
 15→
 16→  const wsRef = useRef(null);
 17→  const roomIdRef = useRef(roomId);
 18→  roomIdRef.current = roomId;
 19→
 20→  const headers = useCallback(() => ({
 21→    'Content-Type': 'application/json',
 22→    'Authorization': `Bearer ${serverToken}`,
 23→  }), [serverToken]);
 24→
 25→  // Fetch room state from server
 26→  const fetchRoom = useCallback(async () => {
 27→    if (!serverToken || !roomId) return;
 28→
 29→    try {
 30→      const resp = await fetch(`${GAME_SERVER_URL}/api/rooms/${roomId}`, {
 31→        headers: { 'Authorization': `Bearer ${serverToken}` },
 32→      });
 33→
 34→      if (!resp.ok) {
 35→        const data = await resp.json().catch(() => ({}));
 36→        setError(data.error || 'Failed to fetch room');
 37→        setStatus('error');
 38→        return;
 39→      }
 40→
 41→      const data = await resp.json();
 42→      setBoard(data.board);
 43→      setCurrentTurn(data.currentTurn);
 44→      setMyColor(data.myColor);
 45→      setLegalMoves(data.legalMoves || []);
 46→      setMoveHistory(data.moveHistory || []);
 47→      setRoom(data);
 48→
 49→      if (data.result) {
 50→        setGameResult(data.result);
 51→        setStatus('finished');
 52→      } else if (data.status === 'waiting') {
 53→        setStatus('waiting');
 54→      } else {
 55→        setStatus('playing');
 56→      }
 57→    } catch (err) {
 58→      console.error('Fetch room error:', err);
 59→      setError('Network error');
 60→      setStatus('error');
 61→    }
 62→  }, [serverToken, roomId]);
 63→
 64→  // Initial fetch
 65→  useEffect(() => {
 66→    fetchRoom();
 67→  }, [fetchRoom]);
 68→
 69→  // WebSocket connection
 70→  useEffect(() => {
 71→    if (!serverToken || !roomId) return;
 72→
 73→    const ws = new WebSocket(`${GAME_WS_URL}/api/rooms/${roomId}/ws?token=${serverToken}`);
 74→    wsRef.current = ws;
 75→
 76→    ws.onmessage = (event) => {
 77→      const msg = JSON.parse(event.data);
 78→
 79→      switch (msg.event) {
 80→        case 'joined':
 81→          // Our own connection confirmed
 82→          break;
 83→
 84→        case 'join':
 85→          // Another player joined - game is starting
 86→          setStatus('playing');
 87→          fetchRoom();
 88→          break;
 89→
 90→        case 'move': {
 91→          // Play sound before updating state — check capture against current board
 92→          if (msg.data.move) {
 93→            const uci = msg.data.move;
 94→            const cols = 'abcdefgh';
 95→            const toCol = cols.indexOf(uci[2]);
 96→            const toRow = 8 - parseInt(uci[3]);
 97→            const toIndex = toRow * 8 + toCol;
 98→            // Use previous board state (before this move) to detect capture
 99→            setBoard(prev => {
100→              const wasCapture = prev && prev[toIndex] !== 0;
101→              if (wasCapture) { playCaptureSound(); } else { playMoveSound(); }
102→              return msg.data.board || prev;
103→            });
104→          } else if (msg.data.board) {
105→            setBoard(msg.data.board);
106→          }
107→          if (msg.data.currentTurn) setCurrentTurn(msg.data.currentTurn);
108→          if (msg.data.legalMoves) setLegalMoves(msg.data.legalMoves);
109→          if (msg.data.moveHistory) setMoveHistory(msg.data.moveHistory);
110→          break;
111→        }
112→
113→        case 'gameOver':
114→          setGameResult(msg.data.result);
115→          setStatus('finished');
116→          fetchRoom();
117→          break;
118→
119→        case 'playerConnected':
120→        case 'playerDisconnected':
121→          // Could show connection indicators later
122→          break;
123→      }
124→    };
125→
126→    ws.onerror = (err) => {
127→      console.error('WebSocket error:', err);
128→    };
129→
130→    ws.onclose = () => {
131→      wsRef.current = null;
132→    };
133→
134→    return () => {
135→      ws.close();
136→      wsRef.current = null;
137→    };
138→  }, [serverToken, roomId, fetchRoom]);
139→
140→  // Submit a move via REST
141→  const submitMove = useCallback(async (uciStr) => {
142→    if (!serverToken || !roomId) return { ok: false };
143→
144→    try {
145→      const resp = await fetch(`${GAME_SERVER_URL}/api/rooms/${roomId}/move`, {
146→        method: 'POST',
147→        headers: headers(),
148→        body: JSON.stringify({ move: uciStr }),
149→      });
150→
151→      const data = await resp.json();
152→
153→      if (!resp.ok) {
154→        console.error('Move rejected:', data.error);
155→        return { ok: false, error: data.error };
156→      }
157→
158→      // Use response data directly instead of re-fetching
159→      if (data.board) setBoard(data.board);
160→      if (data.currentTurn) setCurrentTurn(data.currentTurn);
161→      if (data.legalMoves) setLegalMoves(data.legalMoves);
162→      if (data.moveHistory) setMoveHistory(data.moveHistory);
163→
164→      if (data.gameOver) {
165→        setGameResult(data.result);
166→        setStatus('finished');
167→      }
168→
169→      return { ok: true, data };
170→    } catch (err) {
171→      console.error('Submit move error:', err);
172→      return { ok: false, error: 'Network error' };
173→    }
174→  }, [serverToken, roomId, headers, fetchRoom]);
175→
176→  // Apply move optimistically on the client before server responds
177→  const applyOptimisticMove = useCallback((fromIndex, toIndex) => {
178→    setBoard(prev => {
179→      if (!prev) return prev;
180→      const newBoard = [...prev];
181→      newBoard[toIndex] = newBoard[fromIndex];
182→      newBoard[fromIndex] = 0;
183→      return newBoard;
184→    });
185→    setCurrentTurn(prev => prev === 'white' ? 'black' : 'white');
186→    setLegalMoves([]); // Clear until server responds
187→  }, []);
188→
189→  // Get valid target squares for a source square from server legal moves
190→  const getValidMovesForSquare = useCallback((sourceIndex) => {
191→    const cols = 'abcdefgh';
192→    const sourceFile = cols[sourceIndex % 8];
193→    const sourceRank = 8 - Math.floor(sourceIndex / 8);
194→    const sourceStr = sourceFile + sourceRank;
195→
196→    const targets = [];
197→    for (const uci of legalMoves) {
198→      if (uci.startsWith(sourceStr)) {
199→        const targetFile = uci[2];
200→        const targetRank = parseInt(uci[3]);
201→        const targetCol = cols.indexOf(targetFile);
202→        const targetRow = 8 - targetRank;
203→        const targetIndex = targetRow * 8 + targetCol;
204→        targets.push(targetIndex);
205→      }
206→    }
207→
208→    // Deduplicate (promotions create multiple moves for same target)
209→    return [...new Set(targets)];
210→  }, [legalMoves]);
211→
212→  return {
213→    board,
214→    currentTurn,
215→    myColor,
216→    legalMoves,
217→    moveHistory,
218→    gameResult,
219→    status,
220→    error,
221→    room,
222→    submitMove,
223→    applyOptimisticMove,
224→    getValidMovesForSquare,
225→    fetchRoom,
226→  };
227→}
