const findUserRooms = db.prepare(`
  SELECT r.*, gs.current_turn, gs.move_history
  FROM rooms r
  JOIN game_states gs ON gs.room_id = r.id
  WHERE (r.white_user_id = ? OR r.black_user_id = ?)
