      moveHistory: gameState.moveHistory,
      legalMoves,
      board: gameState.board
    });
  });

  // POST /api/rooms/:id/move — submit a move
  router.post('/:id/move', (req, res) => {
    const roomId = parseInt(req.params.id);
    if (isNaN(roomId)) {
